-- ES/DE/FR translations for all 8 Spain milestones.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2g-face', 'es', 'Facturación electrónica B2G obligatoria (Ley 25/2013)', 'Las facturas a organismos públicos españoles deben presentarse en formato XML Facturae a través de la plataforma FACe — una factura en papel o un PDF simple no es válido y no se procesará.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2g-face', 'de', 'B2G-E-Rechnungsstellung verpflichtend (Ley 25/2013)', 'Rechnungen an spanische öffentliche Stellen müssen im Facturae-XML-Format über die FACe-Plattform eingereicht werden — eine Papierrechnung oder ein einfaches PDF ist nicht gültig und wird nicht verarbeitet.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2g-face', 'fr', 'Facturation électronique B2G obligatoire (Ley 25/2013)', 'Les factures aux organismes publics espagnols doivent être soumises au format XML Facturae via la plateforme FACe — une facture papier ou un simple PDF n''est pas valable et ne sera pas traité.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-sii-introduced', 'es', 'Se introduce el SII', 'Los grandes contribuyentes y declarantes mensuales deben enviar los libros de registro de ventas y compras a la AEAT en un plazo de 4 días, sustituyendo el reporte trimestral por bloques por una visibilidad casi en tiempo real. Las empresas en el SII quedan fuera del alcance de VeriFactu.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-sii-introduced', 'de', 'SII eingeführt', 'Großsteuerzahler und monatliche Melder müssen Verkaufs- und Einkaufsregister innerhalb von 4 Tagen an die AEAT übermitteln, was die vierteljährliche Blockmeldung durch eine nahezu Echtzeit-Sichtbarkeit ersetzt. Unternehmen im SII fallen nicht unter den Anwendungsbereich von VeriFactu.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-sii-introduced', 'fr', 'Le SII est introduit', 'Les grands contribuables et déclarants mensuels doivent envoyer les registres de ventes et d''achats à l''AEAT dans un délai de 4 jours, remplaçant la déclaration trimestrielle par blocs par une visibilité quasi en temps réel. Les entreprises soumises au SII sont hors du champ d''application de VeriFactu.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-crea-y-crece-law', 'es', 'Se promulga la Ley Crea y Crece (Ley 18/2022)', 'Establece el marco legal que exige la facturación electrónica B2B estructurada — pero, al ser una ley marco, deja el detalle técnico y las fechas exactas de inicio a una futura orden ministerial de desarrollo.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-crea-y-crece-law', 'de', 'Das Crea-y-Crece-Gesetz wird erlassen (Ley 18/2022)', 'Schafft den rechtlichen Rahmen, der strukturierte B2B-E-Rechnungsstellung vorschreibt — überlässt jedoch als Rahmengesetz die technischen Details und die genauen Startdaten einer künftigen Durchführungsverordnung des Ministeriums.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-crea-y-crece-law', 'fr', 'La loi Crea y Crece est promulguée (Ley 18/2022)', 'Établit le cadre légal imposant la facturation électronique B2B structurée — mais, en tant que loi-cadre, laisse le détail technique et les dates de démarrage exactes à un futur arrêté ministériel d''application.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-rrsif-published', 'es', 'Se publica el Real Decreto 1007/2023 — RRSIF', 'Establece los requisitos técnicos para los sistemas de facturación (Reglamento de requisitos de los sistemas informáticos de facturación) que sustentan VeriFactu: cadenas de hash criptográficas, sellos de tiempo seguros y firmas electrónicas para evitar la alteración no detectada de los registros.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-rrsif-published', 'de', 'Königliches Dekret 1007/2023 — RRSIF veröffentlicht', 'Legt die technischen Anforderungen für Rechnungssysteme fest (Reglamento de requisitos de los sistemas informáticos de facturación), die VeriFactu zugrunde liegen: verkettete kryptografische Hashes, sichere Zeitstempel und elektronische Signaturen, um unentdeckte Änderungen an Aufzeichnungen zu verhindern.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-rrsif-published', 'fr', 'Le décret royal 1007/2023 — RRSIF est publié', 'Fixe les exigences techniques pour les systèmes de facturation (Reglamento de requisitos de los sistemas informáticos de facturación) sous-tendant VeriFactu : chaînes de hachage cryptographiques, horodatage sécurisé et signatures électroniques pour empêcher toute altération non détectée des registres.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'es', 'Software de facturación certificado VeriFactu — contribuyentes corporativos', 'Las empresas sujetas al Impuesto sobre Sociedades deben usar software de facturación certificado por VeriFactu (RRSIF) que garantice la integridad, trazabilidad e inmutabilidad de los registros de facturación enviados a la Agencia Tributaria (AEAT).', '["Confirme que su software de facturación está certificado por VeriFactu y genera la cadena de hash y el código QR requeridos", "Esta es una obligación separada del mandato más amplio de facturación electrónica B2B de Crea y Crece descrito más abajo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'de', 'VeriFactu-zertifizierte Rechnungssoftware — Körperschaftsteuerpflichtige', 'Unternehmen, die der Körperschaftsteuer unterliegen, müssen VeriFactu-zertifizierte Rechnungssoftware (RRSIF) verwenden, die die Integrität, Nachvollziehbarkeit und Unveränderlichkeit der an die Agencia Tributaria (AEAT) übermittelten Rechnungsdaten gewährleistet.', '["Bestätigen Sie, dass Ihre Rechnungssoftware VeriFactu-zertifiziert ist und die erforderliche Hash-Kette und den QR-Code erzeugt", "Dies ist eine eigenständige Pflicht, getrennt von der umfassenderen B2B-E-Invoicing-Vorgabe von Crea y Crece weiter unten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'fr', 'Logiciel de facturation certifié VeriFactu — contribuables soumis à l''IS', 'Les entreprises soumises à l''impôt sur les sociétés doivent utiliser un logiciel de facturation certifié VeriFactu (RRSIF) garantissant l''intégrité, la traçabilité et l''inaltérabilité des registres de facturation transmis à l''Agencia Tributaria (AEAT).', '["Confirmez que votre logiciel de facturation est certifié VeriFactu et génère la chaîne de hachage et le code QR requis", "Il s''agit d''une obligation distincte de l''obligation plus large de facturation électronique B2B de Crea y Crece décrite ci-dessous"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'es', 'VeriFactu obligatorio — todos los demás contribuyentes', 'La obligación de VeriFactu se extiende a todos los contribuyentes restantes obligados a llevar registros de facturación, incluidos los autónomos y otros profesionales sujetos al IRPF.', '["Autónomos: confirmen que disponen de software de facturación certificado bien antes de esta fecha", "Las empresas que ya usan el sistema de reporte en tiempo real SII quedan exentas de VeriFactu"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'de', 'VeriFactu verpflichtend — alle übrigen Steuerpflichtigen', 'Die VeriFactu-Pflicht erstreckt sich auf alle übrigen zur Führung von Rechnungsdaten verpflichteten Steuerpflichtigen, einschließlich Selbstständiger und anderer der Einkommensteuer unterliegender Berufstätiger.', '["Selbstständige/Freiberufler: Bestätigen Sie, dass zertifizierte Rechnungssoftware weit vor diesem Datum vorhanden ist", "Unternehmen, die bereits das SII-Echtzeit-Meldesystem nutzen, sind von VeriFactu befreit"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'fr', 'VeriFactu obligatoire — tous les autres contribuables', 'L''obligation VeriFactu s''étend à tous les autres contribuables tenus de conserver des registres de facturation, y compris les indépendants et autres professionnels soumis à l''impôt sur le revenu des personnes physiques.', '["Indépendants : confirmez qu''un logiciel de facturation certifié est en place bien avant cette date", "Les entreprises utilisant déjà le système de déclaration en temps réel SII sont exemptées de VeriFactu"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'es', 'Facturación electrónica B2B de Crea y Crece — grandes empresas (>8 millones € de facturación)', 'La facturación electrónica B2B estructurada se vuelve obligatoria para las grandes empresas bajo la ley Crea y Crece, intercambiada a través de plataformas privadas (con copia obligatoria a la plataforma estatal) o de la solución pública gratuita (SPFE), funcionando junto con VeriFactu.', '["Elija una plataforma privada de facturación electrónica (debe reenviar una copia a la SPFE) o use directamente la plataforma pública", "Confirme formatos conformes con EN 16931 (UBL, Facturae, CII)", "Reporte el estado de la factura — aceptada, rechazada o pagada — a la AEAT en un plazo de 4 días naturales"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'de', 'Crea-y-Crece-B2B-E-Rechnungsstellung — Großunternehmen (>8 Mio. € Umsatz)', 'Strukturierte B2B-E-Rechnungsstellung wird für Großunternehmen im Rahmen des Crea-y-Crece-Gesetzes verpflichtend, ausgetauscht über private Plattformen (mit obligatorischer Kopie an die staatliche Plattform) oder die kostenlose öffentliche Lösung (SPFE), parallel zu VeriFactu.', '["Wählen Sie eine private E-Invoicing-Plattform (muss eine Kopie an die SPFE weiterleiten) oder nutzen Sie direkt die öffentliche Plattform", "Bestätigen Sie EN-16931-konforme Formate (UBL, Facturae, CII)", "Melden Sie den Rechnungsstatus — angenommen, abgelehnt oder bezahlt — der AEAT innerhalb von 4 Kalendertagen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'fr', 'Facturation électronique B2B Crea y Crece — grandes entreprises (>8 millions € de chiffre d''affaires)', 'La facturation électronique B2B structurée devient obligatoire pour les grandes entreprises en vertu de la loi Crea y Crece, échangée via des plateformes privées (avec copie obligatoire à la plateforme étatique) ou la solution publique gratuite (SPFE), fonctionnant en parallèle de VeriFactu.', '["Choisissez une plateforme privée de facturation électronique (doit transmettre une copie à la SPFE) ou utilisez directement la plateforme publique", "Confirmez des formats conformes à l''EN 16931 (UBL, Facturae, CII)", "Signalez le statut de la facture — acceptée, rejetée ou payée — à l''AEAT dans un délai de 4 jours calendaires"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'es', 'Facturación electrónica B2B de Crea y Crece — todas las empresas restantes', 'El mandato de facturación electrónica B2B se extiende a las PYME, autónomos y todas las demás empresas registradas a efectos de IVA, completando la reforma española de facturación electrónica de doble vía.', '["Finalice la elección de plataforma e integración con suficiente antelación al plazo", "La Orden Ministerial final seguía pendiente a mediados de 2026 — confirme esta fecha más cerca del momento"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'de', 'Crea-y-Crece-B2B-E-Rechnungsstellung — alle übrigen Unternehmen', 'Die B2B-E-Invoicing-Vorgabe erstreckt sich auf KMU, Einzelunternehmer und alle übrigen umsatzsteuerpflichtigen Unternehmen und schließt damit Spaniens zweigleisige E-Invoicing-Reform ab.', '["Schließen Sie die Plattformwahl und Integration rechtzeitig vor der Frist ab", "Die endgültige Ministerialverordnung stand Mitte 2026 noch aus — bestätigen Sie dieses Datum näher am Zeitpunkt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'fr', 'Facturation électronique B2B Crea y Crece — toutes les entreprises restantes', 'L''obligation de facturation électronique B2B s''étend aux PME, indépendants et toutes les autres entreprises assujetties à la TVA, achevant la réforme espagnole de facturation électronique à double voie.', '["Finalisez le choix de plateforme et l''intégration bien avant l''échéance", "L''arrêté ministériel final restait en attente à la mi-2026 — confirmez cette date plus près de l''échéance"]');
